 if(page==='settings'){label='MAC CLIENT';title='Your game, connected.';note='The app manages your Fabric core and sends controls to Minecraft over an authenticated local connection. Modules operate inside the game.';}
 if(page==='camera-settings'){label='FREECAM SPEED';title='Slow or supersonic.';note='Set 0.5–2560 blocks/s. Hold your Minecraft sprint key for a 3× boost. Your body stays in place; distant terrain still needs to be received.';}
 if(page==='assist-settings'){label='RIGHT-CLICK ASSIST';title='Your click starts it.';note='Place your anchor or crystal normally. The enabled module follows your placement. Crystal attacks react to received spawns and retry if the entity remains; manual blast checks are optional.';}
 if(page==='finder-settings'){label='SELECTED EVIDENCE';title='Candidate signals.';note='Choose received blocks and tracked armor stands. Individual chest models are orange; the separate Storage chunk category is red. J opens full in-game analysis.';}
