 if(page==='texture-packs'){label='YOUR PVP LOOK';title=connectionState.texturePacks?.loading?'Applying textures…':'Your look. One switch.';note=connectionState.texturePacks?.error||'Choose a texture pack and a separate totem style, then return to Minecraft. Turning it off keeps your other resource packs. Maximum FPS removes frame limits without changing your visual settings.';}
 if(page==='mouse-customize'){label='YOUR MOUSE';title='Every click. Your choice.';note='Choose a mouse button, then its recorded click and volume. Each physical press plays once. Changes save automatically.';}
 if(page==='keyboard-customize'){label='YOUR KEYBOARD';title='Every key. Your choice.';note='Choose a key on the keyboard, then a recorded switch below. Base sound applies to every key without its own assignment. Changes save automatically.';}
 if(page==='item-finder'){label='ITEM FINDER';title='Keep track of the loot.';note='Choose from 50 item types. Live markers show dropped stacks and their chunks, with names, counts and distance.';}
