 if(page==='trial-chambers'){label='TRIAL CHAMBERS';title='One key. One opening.';note='Select the normal or ominous vault, choose a preview and arm once. Keep the vault under your crosshair. The matching key is equipped automatically. Preview timing does not control random rewards.';}
 if(page==='stream'){label='CHAT TOOLS';title='Preview before you send.';note='One player name, your own messages and a clear Start or Stop. Only an explicit Start sends chat. The sequence stops when you leave the world.';}
 if(page==='media-settings'){label='YOUR ATMOSPHERE';title='A view of your own.';note=connectionState.media?.error||'Choose a wide image for a sky that wraps around your world. Keep the crosshair light and add missing PigBlack sounds while preserving each pack’s own audio.';}
