 return `<aside class="portrait"><div class="portrait-eyebrow">${home?'LOBBY DANCER':page==='findings'?'FINDINGS COMPANION':pvp?'PVP COMPANION':'WORLD COMPANION'}</div>${asset(pic,'portrait-image '+(home?'dancer':''),'Tung Tung character')}<div class="portrait-title">TUNG TUNG</div><div class="portrait-subtitle">CLIENT</div></aside><aside class="detail"><div class="detail-eyebrow">${label}</div><div class="detail-title">${escapeHTML(title)}</div><div class="detail-note ${movement?'movement-detail-note':''}">${escapeHTML(note)}</div><div class="detail-chip ${movement?'movement-detail-status runtime-'+movement.kind:''}">${movement?movement.label:connected()?'LIVE CORE CONNECTION':'CONNECT MINECRAFT TO USE MODULES'}</div></aside>`;
