 moduleDescriptionId=null;selected=id;
 const pages={item_finder:'item-finder',elytra_finder:'elytra-finder',chunk_finder:'finder-settings',freecam:'camera-settings',player_esp:'player-settings',player_info:'player-settings',diamond_esp:'resource-highlights',ore_esp:'resource-highlights',lava_esp:'resource-highlights'};
