function liveFindings(){return connected()&&Array.isArray(connectionState.findings)?connectionState.findings:[];}
function findingId(f){return [f.x,f.y,f.z,f.kind].join('/');}
function selectedFinding(){return liveFindings().find(f=>findingId(f)===findingKey);}
function canShowInGame(){const finder=modules().find(m=>m.id==='chunk_finder');return canMutate()&&finder?.known&&finder.available&&!busy.has('show-in-game')&&!busy.has('module:chunk_finder');}
function showInGame(){
 if(!canShowInGame())return;
 let epoch;try{epoch=captureEpoch();}catch(error){notify(error.message);return;}
 busy.add('show-in-game');busy.add('module:chunk_finder');render();
 commandQueue=commandQueue.catch(()=>{}).then(async()=>{
  assertEpoch(epoch);
  let finder=modules().find(m=>m.id==='chunk_finder');
  if(!finder?.known||!finder.available)throw new Error('Chunk Finder is unavailable in the current Minecraft core.');
  if(!finder.enabled){
   await nativeRequest('module',{id:'chunk_finder',enabled:true,bridgeGeneration:epoch.generation});
   assertEpoch(epoch);
   finder=modules().find(m=>m.id==='chunk_finder');
   if(!finder?.known||!finder.available||!finder.enabled)throw new Error('Minecraft did not confirm that Chunk Finder was enabled.');
  }
  assertEpoch(epoch);
  return nativeRequest('action',{action:'resume',bridgeGeneration:epoch.generation});
 }).catch(error=>notify(error.message)).finally(()=>{busy.delete('show-in-game');busy.delete('module:chunk_finder');render();});
 return commandQueue;
}
