 if(rows.length)html+=`<div class="findings-list">${rows.slice(findingsOffset,findingsOffset+7).map(f=>`<button class="finding-row ${findingId(f)===findingKey?'chosen':''}" data-finding="${escapeHTML(findingId(f))}"><span class="finding-kind">${escapeHTML(f.kind)} · ${f.loaded?'loaded observation':'history'}</span><span class="finding-position">X ${escapeHTML(f.x)} Y ${escapeHTML(f.y)} Z ${escapeHTML(f.z)}</span><span class="finding-reasons">${escapeHTML(f.reasons||'')}</span><span class="finding-score">${escapeHTML(f.score)}</span></button>`).join('')}</div>`+button('↑',781,611,36,'data-findings-scroll="-1"')+button('↓',831,611,36,'data-findings-scroll="1"');
