 const markup=sidebar()+chrome()+content+rightPanel()+moduleDescription()+`<footer class="footer">${page==='chess'?chessFooter():isRobloxPage()?robloxFooter():connected()?'CONNECTED · '+escapeHTML(connectionState.server):nativeHandler()?'CORE DISCONNECTED · Start your Fabric profile':'NATIVE APP REQUIRED · Open Tung Tung Client.app'}<span class="footer-right">TUNG TUNG CLIENT / macOS ${escapeHTML(preferences.version||'1.33.1')}</span></footer>`;
